public class Enemy : MonoBehaviour
{
    private int _health = 100;

    public void TakeDamage(int amount)
    {
        _health -= amount;
        if (_health <= 0)
            Destroy(gameObject);
    }
}

public static class MathUtils
{
    public static float Lerp(float a, float b, float t)
    {
        return a + (b - a) * t;
    }

    public static float Clamp(float value, float min, float max)
    {
        return Mathf.Clamp(value, min, max);
    }
}

public class Player
{
    private int _health = 100;

    public int GetHealth() { return _health; }

    public void SetHealth(int value) { _health = value; }
    public void SetHealth(float value) { _health = (int)value; }
    public void SetHealth(int value, int max) { _health = Mathf.Min(value, max); }
}

public class Character
{
    private int _health = 100;

    public bool IsAlive()
    {
        return _health > 0;
    }

    public bool HasFullHealth()
    {
        return _health >= 100;
    }
}

public class Weapon
{
    public float CalculateDamage(float baseDamage, float critMultiplier, bool isCritical)
    {
        if (isCritical)
            return baseDamage * critMultiplier;
        return baseDamage;
    }
}

